-- Tenant tax configuration, multiple taxes per quotation line, and cess calculations for PostgreSQL.
BEGIN;
CREATE TABLE "TaxMasters" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(160) NOT NULL,"Kind" VARCHAR(20) NOT NULL,"CalculationBasis" VARCHAR(30) NOT NULL,"Rate" NUMERIC(12,4) NOT NULL,"IsDefault" BOOLEAN NOT NULL,"Description" VARCHAR(500),"IsActive" BOOLEAN NOT NULL,"CreatedAtUtc" TIMESTAMPTZ NOT NULL,"UpdatedAtUtc" TIMESTAMPTZ NOT NULL,UNIQUE("TenantId","Code"));
CREATE INDEX "IX_TaxMasters_Tenant" ON "TaxMasters"("TenantId");
CREATE TABLE "QuotationLineTaxes" ("SerialNo" INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,"Id" UUID NOT NULL UNIQUE,"TenantId" UUID NOT NULL REFERENCES "Tenants"("Id"),"QuotationLineId" UUID NOT NULL REFERENCES "QuotationLines"("Id") ON DELETE CASCADE,"TaxMasterId" UUID NOT NULL REFERENCES "TaxMasters"("Id"),"Code" VARCHAR(40) NOT NULL,"Name" VARCHAR(160) NOT NULL,"Kind" VARCHAR(20) NOT NULL,"CalculationBasis" VARCHAR(30) NOT NULL,"Rate" NUMERIC(12,4) NOT NULL,"TaxableBase" NUMERIC(18,2) NOT NULL,"Amount" NUMERIC(18,2) NOT NULL);
CREATE INDEX "IX_QuotationLineTaxes_Tenant" ON "QuotationLineTaxes"("TenantId"); CREATE INDEX "IX_QuotationLineTaxes_Line" ON "QuotationLineTaxes"("QuotationLineId","SerialNo");
INSERT INTO "TaxMasters"("Id","TenantId","Code","Name","Kind","CalculationBasis","Rate","IsDefault","Description","IsActive","CreatedAtUtc","UpdatedAtUtc")
SELECT (md5(t."Id"::text||':tax:'||d.code))::uuid,t."Id",d.code,d.name,d.kind,d.basis,d.rate,d.is_default,d.description,TRUE,NOW(),NOW() FROM "Tenants" t CROSS JOIN (VALUES
('CGST_9','CGST 9%','TAX','TAXABLE_AMOUNT',9.0000,TRUE,'Central Goods and Services Tax'),('SGST_9','SGST 9%','TAX','TAXABLE_AMOUNT',9.0000,TRUE,'State Goods and Services Tax'),('IGST_18','IGST 18%','TAX','TAXABLE_AMOUNT',18.0000,FALSE,'Integrated Goods and Services Tax'),('CESS_1','Cess 1%','CESS','TAXABLE_AMOUNT',1.0000,FALSE,'Optional cess on taxable amount'),('CESS_ON_TAX_1','Cess 1% on tax','CESS','TAX_AMOUNT',1.0000,FALSE,'Optional cess calculated on selected standard taxes')) d(code,name,kind,basis,rate,is_default,description) ON CONFLICT("TenantId","Code") DO NOTHING;
COMMIT;
